// Capture form metadata and pass binary through
const item = $input.first();
const formData = item.json;
const binary = item.binary || {};
const binaryKey = Object.keys(binary)[0] || 'Contract_File';
const file = binary[binaryKey] || {};

return [{
  json: {
    organisationName: formData['Organisation Name'] || 'Unknown',
    organisationIndustry: formData['Industry'] || 'Other',
    fileName: file.fileName || 'unknown',
    mimeType: file.mimeType || '',
    binaryKey: binaryKey
  },
  binary: item.binary
}];

const item = $input.first();
const metadata = $('Set Metadata').first().json;
const base64Data = item.json.data;

if (!base64Data || base64Data.length < 100) {
  return [{ json: {
    error: true,
    message: 'No base64 data extracted from file',
    organisationName: metadata.organisationName,
    fileName: metadata.fileName
  }}];
}

return [{ json: {
  base64Data: base64Data,
  organisationName: metadata.organisationName,
  organisationIndustry: metadata.organisationIndustry,
  fileName: metadata.fileName
}}];

const item = $input.first();
return [{ json: {
  success: false,
  error: item.json.message || 'Text extraction failed',
  organisationName: item.json.organisationName,
  fileName: item.json.fileName
}}];

const item = $input.first();
const metadata = $('Build Request').first().json;

let parsed;
try {
  let text = item.json.choices?.[0]?.message?.content || item.json.output || '';
  if (typeof text === 'object') text = JSON.stringify(text);

  text = text.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

  const jsonStart = text.indexOf('{');
  const jsonEnd = text.lastIndexOf('}');
  if (jsonStart !== -1 && jsonEnd !== -1) {
    text = text.substring(jsonStart, jsonEnd + 1);
  }

  parsed = JSON.parse(text);
} catch (e) {
  return [{ json: {
    error: true,
    parseError: 'Failed to parse AI response as JSON: ' + e.message,
    rawOutput: String(item.json.choices?.[0]?.message?.content || item.json.output || '').substring(0, 500),
    organisationName: metadata.organisationName,
    fileName: metadata.fileName
  }}];
}

let notSpecifiedCount = 0;
const countNS = (obj) => {
  if (typeof obj === 'string' && obj.toUpperCase().includes('NOT SPECIFIED')) notSpecifiedCount++;
  else if (Array.isArray(obj)) obj.forEach(i => countNS(i));
  else if (typeof obj === 'object' && obj !== null) Object.values(obj).forEach(v => countNS(v));
};
countNS(parsed);

return [{ json: {
  ...parsed,
  _notSpecifiedCount: notSpecifiedCount,
  _organisationName: metadata.organisationName,
  _organisationIndustry: metadata.organisationIndustry,
  _fileName: metadata.fileName,
  _processedAt: new Date().toISOString()
}}];

const item = $input.first();
return [{ json: {
  success: false,
  error: item.json.parseError || 'Unknown error',
  rawOutput: item.json.rawOutput || '',
  organisationName: item.json.organisationName || item.json._organisationName,
  fileName: item.json.fileName || item.json._fileName
}}];

const items = $input.all();
const data = $('Parse Response').first().json;

if (items.length > 0 && items[0].json.id) {
  return [{ json: { orgRecordId: items[0].json.id, orgExists: true, ...data } }];
} else {
  return [{ json: { orgRecordId: null, orgExists: false, ...data } }];
}

const newOrg = $input.first();
const data = $('Parse Response').first().json;
return [{ json: { orgRecordId: newOrg.json.id, ...data } }];

