    'Trigger Condition': sc.trigger_condition || 'NOT SPECIFIED',
    'Credit Percentage': sc.credit_percentage || 'NOT SPECIFIED',
    Cap: sc.cap_on_credits || 'NOT SPECIFIED',
    'Claim Process': sc.claim_process || 'NOT SPECIFIED',
    'Claim Deadline': sc.claim_deadline || 'NOT SPECIFIED',
    'Clause Reference': sc.exact_clause_reference || 'NOT SPECIFIED',
    Source: 'Extracted'
  });
});

(data.concerns_for_service_provider || []).forEach(c => {
  allRecords.push({
    _type: 'concern',
    _contractId: contractId,
    Concern: c.concern || 'NOT SPECIFIED',
    'Relevant Clause': c.relevant_clause || 'NOT SPECIFIED',
    'Risk Level': c.risk_level || 'MEDIUM',
    Recommendation: c.recommendation || 'NOT SPECIFIED',
    Status: 'Open',
    Source: 'Extracted'
  });
});

(data.breach_clauses || []).forEach(b => {
  allRecords.push({
    _type: 'breach_clause',
    _contractId: contractId,
    'Breach Type': b.breach_type || 'NOT SPECIFIED',
    Consequence: b.consequence || 'NOT SPECIFIED',
    'Cure Period': b.cure_period || 'NOT SPECIFIED',
    'Clause Reference': b.exact_clause_reference || 'NOT SPECIFIED',
    Source: 'Extracted'
  });
});

return allRecords.map(r => ({ json: r }));

const contractRecord = $('Create Contract').first();
const data = $('Parse Response').first().json;

return [{ json: {
  success: true,
  contractRecordId: contractRecord.json.id,
  organisationName: data._organisationName,
  contractTitle: data.contract_metadata?.contract_title || 'Unknown',
  extractionConfidence: data.extraction_confidence?.overall_confidence || 'UNKNOWN',
  notSpecifiedCount: data._notSpecifiedCount || 0,
  slaCount: (data.sla_table || []).length,
  serviceCreditCount: (data.service_credits || []).length,
  concernCount: (data.concerns_for_service_provider || []).length,
  breachClauseCount: (data.breach_clauses || []).length,
  processedAt: data._processedAt,
  message: 'Successfully extracted and stored SLA data'
}}];

const item = $input.first().json;

const requestBody = {
  model: 'gpt-4o',
  temperature: 0,
  max_tokens: 8000,
  messages: [
    {
      role: 'system',
      content: 'You are a contract analysis specialist. Your ONLY job is to extract factual information from the contract document provided. You must NEVER invent, assume, or hallucinate any information.\n\nRULES:\n1. If information is NOT explicitly stated in the contract, return "NOT SPECIFIED" for that field.\n2. Extract exact wording where possible. Use direct quotes for conditions and terms.\n3. If a clause is ambiguous, flag it as "REQUIRES REVIEW" and quote the exact ambiguous text.\n4. Never fill in "typical" or "industry standard" values. Only extract what is written.\n5. Respond with ONLY valid JSON. No markdown code fences. No preamble. No explanation.\n\nExtract into this exact JSON structure:\n\n{"contract_metadata":{"contract_title":"","effective_date":"","expiry_date":"","review_date":"","auto_renewal":"","notice_period_days":"","governing_law":"","service_provider":"","service_consumer":"","contract_reference":""},"sla_table":[{"priority":"","description":"","response_time":"","resolution_time":"","mitigation_time":"","availability_target":"","measurement_period":"","conditions_triggering_this_priority":"","exact_contract_clause_reference":"","penalties_or_credits":""}],"uptime_commitments":[{"target_percentage":"","measurement_window":"","exclusions":"","calculation_method":"","exact_clause_reference":""}],"service_credits":[{"trigger_condition":"","credit_percentage":"","cap_on_credits":"","claim_process":"","claim_deadline":"","exact_clause_reference":""}],"concerns_for_service_provider":[{"concern":"","relevant_clause":"","risk_level":"HIGH / MEDIUM / LOW","recommendation":""}],"breach_clauses":[{"breach_type":"","consequence":"","cure_period":"","exact_clause_reference":""}],"key_contacts":{"provider_contact":"","consumer_contact":"","escalation_path":""},"extraction_confidence":{"overall_confidence":"HIGH / MEDIUM / LOW","fields_marked_not_specified":[],"fields_requiring_review":[],"notes":""}}\n\nThe extraction_confidence section is mandatory. List every field you could NOT find.'
    },
    {
      role: 'user',
      content: [
        {
          type: 'file',
          file: {
            filename: item.fileName,
            file_data: 'data:application/pdf;base64,' + item.base64Data
          }
        },
        {
          type: 'text',
          text: 'Extract ALL SLA information from this contract. Organisation: ' + item.organisationName + '. Respond with ONLY the JSON object.'
        }
      ]
    }
  ]
};

return [{ json: { requestBody, organisationName: item.organisationName, organisationIndustry: item.organisationIndustry, fileName: item.fileName } }];

const contractId = $input.first().json.id;
const data = $('Parse Response').first().json;
let orgRecordId = null;
try { orgRecordId = $('Use Existing Org').first().json.orgRecordId; } catch(e) {}
if (!orgRecordId) {
  try { orgRecordId = $('Set New Org ID').first().json.orgRecordId; } catch(e) {}
}
if (!orgRecordId) {
  try { orgRecordId = $('Create Organisation').first().json.id; } catch(e) {}
}
const allRecords = [];

(data.sla_table || []).forEach(sla => {
  allRecords.push({
    _type: 'sla_priority',
    _contractId: contractId,
    _orgRecordId: orgRecordId,
    Name: (sla.priority || 'SLA') + ' - ' + (sla.description || '').substring(0, 50),
    Priority: sla.priority || 'NOT SPECIFIED',
    Description: sla.description || 'NOT SPECIFIED',
    'Response Time': sla.response_time || 'NOT SPECIFIED',
    'Resolution Time': sla.resolution_time || 'NOT SPECIFIED',
    'Mitigation Time': sla.mitigation_time || 'NOT SPECIFIED',
    'Availability Target': sla.availability_target || 'NOT SPECIFIED',
    'Measurement Period': sla.measurement_period || 'NOT SPECIFIED',
    'Trigger Conditions': sla.conditions_triggering_this_priority || 'NOT SPECIFIED',
    'Clause Reference': sla.exact_contract_clause_reference || 'NOT SPECIFIED',
    Penalties: sla.penalties_or_credits || 'NOT SPECIFIED',
    Source: 'Extracted'
  });
});

const uptimeArr = Array.isArray(data.uptime_commitments) ? data.uptime_commitments : [data.uptime_commitments];
uptimeArr.filter(Boolean).forEach((u, i) => {
  allRecords.push({
    _type: 'uptime_commitment',
    _contractId: contractId,
    _orgRecordId: orgRecordId,
    Name: 'Uptime ' + (u.target_percentage || 'Commitment ' + (i + 1)),
    'Target Percentage': u.target_percentage || 'NOT SPECIFIED',
    'Measurement Window': u.measurement_window || 'NOT SPECIFIED',
    Exclusions: u.exclusions || 'NOT SPECIFIED',
    'Calculation Method': u.calculation_method || 'NOT SPECIFIED',
    'Clause Reference': u.exact_clause_reference || 'NOT SPECIFIED',
    Source: 'Extracted'
  });
});

(data.service_credits || []).forEach((sc, i) => {
  allRecords.push({
    _type: 'service_credit',
    _contractId: contractId,
    _orgRecordId: orgRecordId,
    Name: 'Credit ' + (sc.credit_percentage || 'Tier ' + (i + 1)),
    'Trigger Condition': sc.trigger_condition || 'NOT SPECIFIED',
    'Credit Percentage': sc.credit_percentage || 'NOT SPECIFIED',
    Cap: sc.cap_on_credits || 'NOT SPECIFIED',
    'Claim Process': sc.claim_process || 'NOT SPECIFIED',
    'Claim Deadline': sc.claim_deadline || 'NOT SPECIFIED',
    'Clause Reference': sc.exact_clause_reference || 'NOT SPECIFIED',
    Source: 'Extracted'
  });
});

(data.concerns_for_service_provider || []).forEach((c, i) => {
  allRecords.push({
    _type: 'concern',
    _contractId: contractId,
    _orgRecordId: orgRecordId,
    Name: (c.risk_level || 'Risk') + ' - ' + (c.concern || '').substring(0, 50),
    Concern: c.concern || 'NOT SPECIFIED',
    'Relevant Clause': c.relevant_clause || 'NOT SPECIFIED',
    'Risk Level': c.risk_level || 'MEDIUM',
    Recommendation: c.recommendation || 'NOT SPECIFIED',
    Status: 'Open',
    Source: 'Extracted'
  });
});

(data.breach_clauses || []).forEach((b, i) => {
  allRecords.push({
    _type: 'breach_clause',
    _contractId: contractId,
    _orgRecordId: orgRecordId,
    Name: (b.breach_type || 'Breach ' + (i + 1)),
    'Breach Type': b.breach_type || 'NOT SPECIFIED',
    Consequence: b.consequence || 'NOT SPECIFIED',
    'Cure Period': b.cure_period || 'NOT SPECIFIED',
    'Clause Reference': b.exact_clause_reference || 'NOT SPECIFIED',
