return allRecords.map(r => ({ json: r }));

const XLSX = require('xlsx');
const data = $('Parse Response').first().json;
const meta = data.contract_metadata || {};
const wb = XLSX.utils.book_new();

// Sheet 1: Contract Metadata
const metaRows = [
  ['CONTRACT METADATA'],
  ['Field', 'Value'],
  ['Organisation', data._organisationName || ''],
  ['Industry', data._organisationIndustry || ''],
  ['Contract Title', meta.contract_title || 'NOT SPECIFIED'],
  ['Contract Reference', meta.contract_reference || 'NOT SPECIFIED'],
  ['Service Provider', meta.service_provider || 'NOT SPECIFIED'],
  ['Service Consumer', meta.service_consumer || 'NOT SPECIFIED'],
  ['Effective Date', meta.effective_date || 'NOT SPECIFIED'],
  ['Expiry Date', meta.expiry_date || 'NOT SPECIFIED'],
  ['Auto Renewal', meta.auto_renewal || 'NOT SPECIFIED'],
  ['Notice Period (Days)', meta.notice_period_days || 'NOT SPECIFIED'],
  ['Governing Law', meta.governing_law || 'NOT SPECIFIED'],
  ['Extraction Date', new Date().toISOString().split('T')[0]],
  ['Extraction Confidence', (data.extraction_confidence || {}).overall_confidence || 'UNKNOWN']
];
const ws1 = XLSX.utils.aoa_to_sheet(metaRows);
ws1['!cols'] = [{wch: 25}, {wch: 60}];
XLSX.utils.book_append_sheet(wb, ws1, 'Contract Metadata');

// Sheet 2: SLA Priorities
const slaHeader = ['Priority', 'Description', 'Response Time', 'Resolution Time', 'Mitigation Time', 'Availability Target', 'Measurement Period', 'Trigger Conditions', 'Clause Reference', 'Penalties / Credits'];
const slaRows = [['SLA PRIORITY TABLE'], slaHeader];
(data.sla_table || []).forEach(sla => {
  slaRows.push([
    sla.priority || '', sla.description || '', sla.response_time || '',
    sla.resolution_time || '', sla.mitigation_time || '', sla.availability_target || '',
    sla.measurement_period || '', sla.conditions_triggering_this_priority || '',
    sla.exact_contract_clause_reference || '', sla.penalties_or_credits || ''
  ]);
});
const ws2 = XLSX.utils.aoa_to_sheet(slaRows);
ws2['!cols'] = [{wch:15},{wch:40},{wch:15},{wch:15},{wch:15},{wch:15},{wch:15},{wch:50},{wch:15},{wch:40}];
XLSX.utils.book_append_sheet(wb, ws2, 'SLA Priorities');

// Sheet 3: Uptime & Credits
const uptime = Array.isArray(data.uptime_commitments) ? data.uptime_commitments : [data.uptime_commitments];
const u = uptime.filter(Boolean)[0] || {};
const uptimeRows = [
  ['UPTIME COMMITMENTS'],
  ['Field', 'Details'],
  ['Target Uptime %', u.target_percentage || 'NOT SPECIFIED'],
  ['Measurement Window', u.measurement_window || 'NOT SPECIFIED'],
  ['Exclusions', u.exclusions || 'NOT SPECIFIED'],
  ['Calculation Method', u.calculation_method || 'NOT SPECIFIED'],
  ['Clause Reference', u.exact_clause_reference || 'NOT SPECIFIED'],
  [],
  ['SERVICE CREDITS'],
  ['Trigger Condition', 'Credit %', 'Credit Cap', 'Claim Process', 'Claim Deadline', 'Clause Ref']
];
(data.service_credits || []).forEach(sc => {
  uptimeRows.push([
    sc.trigger_condition || '', sc.credit_percentage || '', sc.cap_on_credits || '',
    sc.claim_process || '', sc.claim_deadline || '', sc.exact_clause_reference || ''
  ]);
});
const ws3 = XLSX.utils.aoa_to_sheet(uptimeRows);
ws3['!cols'] = [{wch:35},{wch:20},{wch:20},{wch:40},{wch:25},{wch:15}];
XLSX.utils.book_append_sheet(wb, ws3, 'Uptime & Credits');

// Sheet 4: Concerns & Risks
const concernRows = [
  ['CONCERNS FOR SERVICE PROVIDER / CONSUMER'],
  ['Concern', 'Relevant Clause', 'Risk Level', 'Recommendation', 'Status']
];
(data.concerns_for_service_provider || []).forEach(c => {
  concernRows.push([c.concern || '', c.relevant_clause || '', c.risk_level || '', c.recommendation || '', 'Open']);
});
const ws4 = XLSX.utils.aoa_to_sheet(concernRows);
ws4['!cols'] = [{wch:50},{wch:15},{wch:12},{wch:50},{wch:12}];
XLSX.utils.book_append_sheet(wb, ws4, 'Concerns & Risks');

// Sheet 5: Breach Clauses
const breachRows = [
  ['BREACH & TERMINATION CLAUSES'],
  ['Breach Type', 'Consequence', 'Cure Period', 'Clause Reference']
];
(data.breach_clauses || []).forEach(b => {
  breachRows.push([b.breach_type || '', b.consequence || '', b.cure_period || '', b.exact_clause_reference || '']);
});
const ws5 = XLSX.utils.aoa_to_sheet(breachRows);
ws5['!cols'] = [{wch:40},{wch:50},{wch:25},{wch:15}];
XLSX.utils.book_append_sheet(wb, ws5, 'Breach Clauses');

// Sheet 6: Extraction Audit
const conf = data.extraction_confidence || {};
const auditRows = [
  ['EXTRACTION CONFIDENCE REPORT'],
  ['Overall Confidence', conf.overall_confidence || 'UNKNOWN'],
  [],
  ['FIELDS MARKED "NOT SPECIFIED"', 'Explanation']
];
(conf.fields_marked_not_specified || []).forEach(f => {
  auditRows.push([typeof f === 'string' ? f : JSON.stringify(f), 'Not found in contract text']);
});
auditRows.push([], ['FIELDS REQUIRING HUMAN REVIEW', 'Reason']);
(conf.fields_requiring_review || []).forEach(f => {
  auditRows.push([typeof f === 'string' ? f : JSON.stringify(f), 'Requires human review']);
});
auditRows.push([], ['NOTES'], [conf.notes || 'AI extraction — verify against source document.']);
const ws6 = XLSX.utils.aoa_to_sheet(auditRows);
ws6['!cols'] = [{wch:40},{wch:60}];
XLSX.utils.book_append_sheet(wb, ws6, 'Extraction Audit');

// Generate binary
const buf = XLSX.write(wb, {type: 'buffer', bookType: 'xlsx'});
const base64 = buf.toString('base64');
const fileName = 'SLA_Extraction_' + (data._organisationName || 'Report').replace(/[^a-zA-Z0-9]/g, '_') + '.xlsx';

return [{
  json: { success: true, fileName: fileName },
  binary: {
    data: {
      data: base64,
      mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      fileName: fileName,
      fileExtension: 'xlsx'
    }
  }
}];
